// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amountA, uint256 amountB, address actor) public {
        vm.assume(amountA <= VALUE_CAP);
        vm.assume(amountB <= VALUE_CAP);
        vm.assume(actor != address(0));
        amountA = bound(amountA, 1, 10 ether);
        amountB = bound(amountB, 0, 10 ether);

        vm.deal(actor, amountA + amountB);
        vm.prank(actor);
        c.Put{value: amountA}(0);
        vm.prank(actor);
        c.Put{value: amountB}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amountA + amountB);
    }
}
